  uint64_t vcpu_off = env_offset.HV_VCPU;
  uint64_t stride = env_offset.HV_VCPU_CPUID;
  if ((!vcpu_off || !stride) && fw >= 0x0300) {
    DEBUG_PRINT("  missing HV_VCPU offsets for fw 0x%04x\n", fw);
