    int kv_dim = VOX_DEC_KV_HEADS * VOX_DEC_HEAD_DIM; 
    size_t elems = (size_t)VOX_DEC_LAYERS * max_seq * kv_dim;
    size_t cache_size_f32 = elems * sizeof(float);
    size_t cache_size_f16 = elems * sizeof(uint16_t);
    ctx->kv_cache_k = NULL;
    ctx->kv_cache_v = NULL;
    ctx->kv_cache_k_f16 = NULL;
