struct netif *
netif_find(const char *name)
{
  struct netif *netif;
  u8_t num;
  LWIP_ASSERT_CORE_LOCKED();
  if (name == NULL) {
    return NULL;
  }
  num = (u8_t)atoi(&name[2]);
  if (!num && (name[2] != '0')) {
    return NULL;
  }
  NETIF_FOREACH(netif) {
    if (num == netif->num &&
        name[0] == netif->name[0] &&
        name[1] == netif->name[1]) {
      LWIP_DEBUGF(NETIF_DEBUG, ("netif_find: found %c%c\n", name[0], name[1]));
      return netif;
    }
  }
  LWIP_DEBUGF(NETIF_DEBUG, ("netif_find: didn't find %c%c\n", name[0], name[1]));
  return NULL;
}

