    char *path;
    int i;
    if (M_FileExists(name))
    {
        return name;
    }
    BuildIWADDirList();
    for (i=0; i<num_iwad_dirs; ++i)
    {
        if (DirIsFile(iwad_dirs[i], name) || M_FileExists(iwad_dirs[i]))
        {
            return strdup(iwad_dirs[i]);
        }
        path = M_StringJoin(iwad_dirs[i], DIR_SEPARATOR_S, name, NULL);
        if (M_FileExists(path))
        {
            return path;
        }
        free(path);
    }
    return NULL;
}

