function buildProviderHeaders(provider, credentials, stream = true, body = null) {
  const config = getProviderConfig(provider);
  const headers = {
    "Content-Type": "application/json",
    ...config.headers
  };
  if (isAnthropicCompatible(provider)) {
    if (credentials.apiKey) {
      headers["x-api-key"] = credentials.apiKey;
    } else if (credentials.accessToken) {
      headers["Authorization"] = `Bearer ${credentials.accessToken}`;
    }
    if (!headers["anthropic-version"]) {
      headers["anthropic-version"] = "2023-06-01";
    }
  } else {
    switch (provider) {
      case "gemini":
        if (credentials.apiKey) {
          headers["x-goog-api-key"] = credentials.apiKey;
        } else if (credentials.accessToken) {
          headers["Authorization"] = `Bearer ${credentials.accessToken}`;
        }
        break;
      case "antigravity":
      case "gemini-cli":
        headers["Authorization"] = `Bearer ${credentials.accessToken}`;
        break;
      case "claude":
        if (credentials.apiKey) {
          headers["x-api-key"] = credentials.apiKey;
        } else if (credentials.accessToken) {
          headers["Authorization"] = `Bearer ${credentials.accessToken}`;
        }
        break;
      case "github": {
        const githubToken = credentials.copilotToken || credentials.accessToken;
        headers["Authorization"] = `Bearer ${githubToken}`;
        headers["Content-Type"] = "application/json";
        headers["copilot-integration-id"] = "vscode-chat";
        headers["editor-version"] = "vscode/1.107.1";
        headers["editor-plugin-version"] = "copilot-chat/0.26.7";
        headers["user-agent"] = "GitHubCopilotChat/0.26.7";
        headers["openai-intent"] = "conversation-panel";
        headers["x-github-api-version"] = "2025-04-01";
        headers["x-request-id"] = crypto.randomUUID ? crypto.randomUUID() : 
          'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
            const r = Math.random() * 16 | 0;
            const v = c != 'x' ? r : (r & 0x3 | 0x8);
            return v.toString(16);
          });
        headers["x-vscode-user-agent-library-version"] = "electron-fetch";
        headers["X-Initiator"] = "user";
        headers["Accept"] = "application/json";
        break;
      }
      case "codex":
      case "qwen":
      case "openai":
      case "openrouter":
        headers["Authorization"] = `Bearer ${credentials.apiKey || credentials.accessToken}`;
        break;
      case "cline":
        Object.assign(headers, buildClineHeaders(credentials.apiKey || credentials.accessToken));
        break;
      case "glm":
      case "kimi":
      case "minimax":
        headers["x-api-key"] = credentials.apiKey;
        break;
      case "vertex":
      case "vertex-partner":
        break;
      default:
        headers["Authorization"] = `Bearer ${credentials.apiKey || credentials.accessToken}`;
        break;
    }
  }
  if (stream) {
    headers["Accept"] = "text/event-stream";
  }
  return headers;
}

