        if(app->psa_bf_thread && app->psa_bf_state) {
            uint8_t bfst = app->psa_bf_state->status;
            if(bfst == PSA_BF_STATUS_IDLE || bfst == PSA_BF_STATUS_RUNNING) {
                sub_decode_show_psa_bf_progress(app);
