function msfix1(gfc) {
    for (var sb = 0; sb < Encoder.SBMAX_l; sb++) {
        if (gfc.thm[0].l[sb] > 1.58 * gfc.thm[1].l[sb]
            || gfc.thm[1].l[sb] > 1.58 * gfc.thm[0].l[sb])
            continue;
        var mld = gfc.mld_l[sb] * gfc.en[3].l[sb];
        var rmid = Math.max(gfc.thm[2].l[sb],
