function calculateSearchAccuracy(results, expectedId) {
  if (results.length === 0) {
    return {
      found: false,
      position: -1,
      accuracy: 0,
    };
  }
  const position = results.findIndex(r => r.id === expectedId);
  return {
    found: position !== -1,
    position: position,
    isFirst: position === 0,
    accuracy: position === 0 ? 100 : position <= 0 ? Math.max(0, 100 - (position * 10)) : 0,
  };
}

