static int parse_past_text_mode(const char *s, int *out_mode) {
    char buf[16];
    size_t n = strlen(s);
    if (n == 0 || n >= sizeof(buf)) return -1;
    for (size_t i = 0; i < n; i++) {
        buf[i] = (char)tolower((unsigned char)s[i]);
    }
    buf[n] = '\0';
    if (strcmp(buf, "yes") == 0) {
        *out_mode = 1;
        return 0;
    }
    if (strcmp(buf, "no") == 0) {
        *out_mode = 0;
        return 0;
    }
    if (strcmp(buf, "auto") == 0) {
        *out_mode = -1;
        return 0;
    }
    return -1;
}

