    case "antigravity": {
      const urlIndex = options?.baseUrlIndex || 0;
      const baseUrl = config.baseUrls[urlIndex] || config.baseUrls[0];
      const path = stream ? "/v1internal:streamGenerateContent?alt=sse" : "/v1internal:generateContent";
