	if (irqs & (1 << RX_DMA_CH_AAL))
		mailbox_aal_rx_handler();
	if (irqs & (1 << RX_DMA_CH_OAM))
		mailbox_oam_rx_handler();
	if ((irqs >> (FIRST_QSB_QID + 16)) & g_atm_priv_data.conn_table)
