		tasklet_schedule(&g_dma_tasklet);
	else if (*MBOX_IGU1_ISR >> (FIRST_QSB_QID + 16)) 
		tasklet_schedule(&g_dma_tasklet);
	else
		enable_irq(g_atm_priv_data.irq);
}

