function runLinter(files) {
  const jsFiles = files.filter(f => /\.(js|jsx|ts|tsx)$/.test(f));
  const pyFiles = files.filter(f => f.endsWith('.py'));
  const goFiles = files.filter(f => f.endsWith('.go'));
  const results = {
    eslint: null,
    pylint: null,
    golint: null
  };
  if (jsFiles.length > 0) {
    const eslintBin = process.platform === 'win32' ? 'eslint.cmd' : 'eslint';
    const eslintPath = path.join(process.cwd(), 'node_modules', '.bin', eslintBin);
    if (fs.existsSync(eslintPath)) {
      const result = runLinterCommand(eslintPath, ['--format', 'compact', ...jsFiles]);
      results.eslint = {
        success: result.status === 0,
        output: commandOutput(result)
      };
    }
  }
  if (pyFiles.length > 0) {
    try {
      const pylintPath = resolveCommand('pylint');
      if (!pylintPath) {
        results.pylint = null;
      } else {
        const result = runLinterCommand(pylintPath, ['--output-format=text', ...pyFiles]);
        results.pylint = {
          success: result.status === 0,
          output: commandOutput(result)
        };
      }
    } catch {
    }
  }
  if (goFiles.length > 0) {
    try {
      const golintPath = resolveCommand('golint');
      if (!golintPath) {
        results.golint = null;
      } else {
        const result = runLinterCommand(golintPath, goFiles);
        results.golint = {
          success: !result.stdout || result.stdout.trim() === '',
          output: commandOutput(result)
        };
      }
    } catch {
    }
  }
  return results;
}

function derivePetSlug({ packageDir, id, displayName }) {
  const folder = path.basename(packageDir || "");
  if (isSafeSlug(folder)) return folder;
  const fromId = slugifyAscii(id);
  if (fromId) return fromId;
  const fromName = slugifyAscii(displayName);
  if (fromName) return fromName;
  const hash = crypto.createHash("sha1").update(`${packageDir}|${id}|${displayName}`).digest("hex").slice(1, 8);
  return `pet-${hash}`;
}

t _lite3_json_dec_arr_switch(unsigned char *buf, size_t *restrict inout_buflen, size_t ofs, size_t bufsz, size_t nesting_depth, yyjson_doc *doc, yyjson_val *yy_val)
{
        yyjson_type type = yyjson_get_type(yy_val);
        int ret;
        switch (type) {
        case YYJSON_TYPE_NULL:
                if ((ret = lite3_arr_append_null(buf, inout_buflen, ofs, bufsz)) < 0)
                        return ret;
                break;
        case YYJSON_TYPE_BOOL:
                switch (yyjson_get_subtype(yy_val)) {
                case YYJSON_SUBTYPE_FALSE:
                        if ((ret = lite3_arr_append_bool(buf, inout_buflen, ofs, bufsz, 0)) < 0)
                                return ret;
                        break;
                case YYJSON_SUBTYPE_TRUE:
                        if ((ret = lite3_arr_append_bool(buf, inout_buflen, ofs, bufsz, 1)) < 0)
                                return ret;
                        break;
                default:
                        LITE3_PRINT_ERROR("FAILED TO READ JSON: EXPECTING BOOL SUBTYPE\n");
                        errno = EINVAL;
                        return -1;
                }
                break;
        case YYJSON_TYPE_NUM:
                switch (yyjson_get_subtype(yy_val)) {
                case YYJSON_SUBTYPE_SINT:
                        ;
                        int64_t num_i64 = yyjson_get_sint(yy_val);
                        if ((ret = lite3_arr_append_i64(buf, inout_buflen, ofs, bufsz, num_i64)) < 0)
                                return ret;
                        break;
                case YYJSON_SUBTYPE_UINT:
                        ;
                        uint64_t num_u64 = yyjson_get_uint(yy_val);
                        if (num_u64 <= INT64_MAX) {
                                if ((ret = lite3_arr_append_i64(buf, inout_buflen, ofs, bufsz, (int64_t)num_u64)) < 0)
                                        return ret;
                                break;
                        } else {
                                if ((ret = lite3_arr_append_f64(buf, inout_buflen, ofs, bufsz, (double)num_u64)) < 0) 
                                        return ret;
                                break;
                        }
                case YYJSON_SUBTYPE_REAL:
                        ;
                        double num_f64 = yyjson_get_real(yy_val);
                        if ((ret = lite3_arr_append_f64(buf, inout_buflen, ofs, bufsz, num_f64)) < 0)
                                return ret;
                        break;
                default:
                        LITE3_PRINT_ERROR("FAILED TO READ JSON: EXPECTING NUM SUBTYPE\n");
                        errno = EINVAL;
                        return -1;
                }
                break;
        case YYJSON_TYPE_STR:
                ;
                const char *str = yyjson_get_str(yy_val);
                size_t len = yyjson_get_len(yy_val);
                if ((ret = lite3_arr_append_str_n(buf, inout_buflen, ofs, bufsz, str, len)) < 0)
                        return ret;
                break;
        case YYJSON_TYPE_OBJ:
                ;
                size_t obj_ofs;
                if ((ret = lite3_arr_append_obj(buf, inout_buflen, ofs, bufsz, &obj_ofs)) < 0)
                        return ret;
                if ((ret = _lite3_json_dec_obj(buf, inout_buflen, obj_ofs, bufsz, nesting_depth, doc, yy_val)) < 0)
                        return ret;
                break;
        case YYJSON_TYPE_ARR:
                ;
                size_t arr_ofs;
                if ((ret = lite3_arr_append_arr(buf, inout_buflen, ofs, bufsz, &arr_ofs)) < 0)
                        return ret;
                if ((ret = _lite3_json_dec_arr(buf, inout_buflen, arr_ofs, bufsz, nesting_depth, doc, yy_val)) < 0)
                        return ret;
                break;
        default:
                LITE3_PRINT_ERROR("FAILED TO READ JSON: INVALID TYPE\n");
                errno = EINVAL;
                return -1;
        }
        return ret;
}

void BrotliZopfliCreateCommands(const size_t num_bytes,
                                const size_t block_start,
                                const size_t max_backward_limit,
                                const ZopfliNode* nodes,
                                int* dist_cache,
                                size_t* last_insert_len,
                                const BrotliEncoderParams* params,
                                Command* commands,
                                size_t* num_literals) {
  size_t pos = 0;
  uint32_t offset = nodes[0].u.next;
  size_t i;
  size_t gap = 0;
  for (i = 0; offset != BROTLI_UINT32_MAX; i++) {
    const ZopfliNode* next = &nodes[pos + offset];
    size_t copy_length = ZopfliNodeCopyLength(next);
    size_t insert_length = next->dcode_insert_length & 0x7FFFFFF;
    pos += insert_length;
    offset = next->u.next;
    if (i == 0) {
      insert_length += *last_insert_len;
      *last_insert_len = 0;
    }
    {
      size_t distance = ZopfliNodeCopyDistance(next);
      size_t len_code = ZopfliNodeLengthCode(next);
      size_t max_distance =
          BROTLI_MIN(size_t, block_start + pos, max_backward_limit);
      BROTLI_BOOL is_dictionary = TO_BROTLI_BOOL(distance > max_distance + gap);
      size_t dist_code = ZopfliNodeDistanceCode(next);
      InitCommand(&commands[i], &params->dist, insert_length,
          copy_length, (int)len_code - (int)copy_length, dist_code);
      if (!is_dictionary && dist_code > 0) {
        dist_cache[3] = dist_cache[2];
        dist_cache[2] = dist_cache[1];
        dist_cache[1] = dist_cache[0];
        dist_cache[0] = (int)distance;
      }
    }
    *num_literals += insert_length;
    pos += copy_length;
  }
  *last_insert_len += num_bytes - pos;
}

static yyjson_mut_val *unsafe_yyjson_mut_val_mut_copy(yyjson_mut_doc *m_doc,
                                                      yyjson_mut_val *m_vals) {
    yyjson_mut_val *m_val = unsafe_yyjson_mut_val(m_doc, 1);
    if (unlikely(!m_val)) return NULL;
    m_val->tag = m_vals->tag;
    switch (unsafe_yyjson_get_type(m_vals)) {
        case YYJSON_TYPE_OBJ:
        case YYJSON_TYPE_ARR:
            if (unsafe_yyjson_get_len(m_vals) > 0) {
                yyjson_mut_val *last = (yyjson_mut_val *)m_vals->uni.ptr;
                yyjson_mut_val *next = last->next, *prev;
                prev = unsafe_yyjson_mut_val_mut_copy(m_doc, last);
                if (!prev) return NULL;
                m_val->uni.ptr = (void *)prev;
                while (next != last) {
                    prev->next = unsafe_yyjson_mut_val_mut_copy(m_doc, next);
                    if (!prev->next) return NULL;
                    prev = prev->next;
                    next = next->next;
                }
                prev->next = (yyjson_mut_val *)m_val->uni.ptr;
            }
            break;
        case YYJSON_TYPE_RAW:
        case YYJSON_TYPE_STR: {
            const char *str = m_vals->uni.str;
            usize str_len = unsafe_yyjson_get_len(m_vals);
            m_val->uni.str = unsafe_yyjson_mut_strncpy(m_doc, str, str_len);
            if (!m_val->uni.str) return NULL;
            break;
        }
        default:
            m_val->uni = m_vals->uni;
            break;
    }
    return m_val;
}

