static int i2c_outb(int c)
{
	int i;
	int ack;
	for (i = 7; i >= 0; i--) {
		if (c & ( 1 << i )) {
			sdahi();
		} else {
			sdalo();
		}
		if (sclhi() < 0) { 
			sdahi(); 
			return -ETIMEDOUT;
		}
		scllo();
	}
	sdahi();
	if (sclhi() < 0) {
		return -ETIMEDOUT;
	}
	ack = getsda() != 0;	
	scllo();
	if (rtc_debug)
		printk(KERN_DEBUG "i2c_outb(0x%02x) -> %s\n",
		       c, ack ? "ACK": "NAK");
	return ack;		
}

