{
	const char *ptr;char *ptr2,*out;int len=0;
	ptr=str;while (*ptr && ++len) {if (*ptr<32 || *ptr=='\"' || *ptr=='\\') len++;ptr++;}
	out=(char*)cJSON_malloc(len+3);
