        (btn_lua_handle_ud_t *)lua_newuserdata(L, sizeof(*ud));
    ud->handle = btn;
    luaL_getmetatable(L, BTN_HANDLE_METATABLE);
    lua_setmetatable(L, -2);
    return 1;
