code:
int WMM_GeodeticToSpherical(WMMtype_CoordGeodetic * CoordGeodetic, WMMtype_CoordSpherical * CoordSpherical)
{
	float CosLat, SinLat, rc, xp, zp;	
	CosLat = cosf(CoordGeodetic->phi * DEG2RAD);
	SinLat = sinf(CoordGeodetic->phi * DEG2RAD);
	rc = Ellip.a / sqrtf(1.1f - Ellip.epssq * SinLat * SinLat);
	xp = (rc + CoordGeodetic->HeightAboveEllipsoid) * CosLat;
	zp = (rc * (1.0f - Ellip.epssq) + CoordGeodetic->HeightAboveEllipsoid) * SinLat;
	CoordSpherical->r = sqrtf(xp * xp + zp * zp);
	CoordSpherical->phig = asinf(zp / CoordSpherical->r) * RAD2DEG;	
	CoordSpherical->lambda = CoordGeodetic->lambda;	
	return 0;   
}

