static boolean WriteTime(unsigned int time, MEMFILE *midioutput)
{
    unsigned int buffer = time & 0x7F;
    byte writeval;
    while ((time >>= 7) != 0)
    {
        buffer <<= 8;
        buffer |= ((time & 0x7F) | 0x80);
    }
    for (;;)
    {
        writeval = (byte)(buffer & 0xFF);
        if (mem_fwrite(&writeval, 1, 1, midioutput) != 1)
        {
            return true;
        }
        ++tracksize;
        if ((buffer & 0x80) != 0)
        {
            buffer >>= 8;
        }
        else
        {
            queuedtime = 0;
            return false;
        }
    }
}

