    rdpq_triangle(&TRIFMT_SHADE, vtx[0], vtx[2], vtx[3]);
    if (anim_part >= 1) {
      rdpq_set_mode_standard();
      rdpq_mode_alphacompare(1);
      rdpq_mode_blender(RDPQ_BLENDER_MULTIPLY);
      rdpq_mode_combiner(RDPQ_COMBINER1((0,0,0,PRIM),(TEX0,0,PRIM,0)));
