static void run_event_cb(const TtWifiEvent* e, void* user) {
    TagTinkerApp* app = user;
    switch(e->type) {
    case TtWifiEvtProgress:
        app->wifi_progress_pct = (uint8_t)e->u0;
        strncpy(app->wifi_progress_msg, e->str0 ? e->str0 : "",
                sizeof(app->wifi_progress_msg) - 1);
        view_dispatcher_send_custom_event(app->view_dispatcher, EVT_PROGRESS);
        break;
    case TtWifiEvtResultBegin: {
        uint16_t w = (uint16_t)(e->u0 & 0xFFFFu);
        uint16_t h = (uint16_t)(e->u0 >> 16);
        uint8_t  pl = (uint8_t)(e->u1 ? e->u1 : 1);
        uint8_t ar = 0xE0, ag = 0x10, ab = 0x10;  
        if(app->selected_target >= 0 && app->selected_target < app->target_count) {
            const TagTinkerTarget* t = &app->targets[app->selected_target];
            if(t->profile.color == TagTinkerTagColorYellow) {
                ar = 0xF0; ag = 0xC0; ab = 0x10;
            }
        }
        if(!tagtinker_wifi_bmp_open(&s_bmp_writer, w, h, pl, ar, ag, ab)) {
            strncpy(app->wifi_last_error, "BMP open failed",
                    sizeof(app->wifi_last_error) - 1);
            view_dispatcher_send_custom_event(app->view_dispatcher, EVT_ERROR);
        }
        break;
    }
    case TtWifiEvtResultChunk:
        tagtinker_wifi_bmp_chunk(&s_bmp_writer, e->data, e->data_len);
        break;
    case TtWifiEvtResultEnd:
        if(!tagtinker_wifi_bmp_close(&s_bmp_writer)) {
            strncpy(app->wifi_last_error, "BMP write failed",
                    sizeof(app->wifi_last_error) - 1);
            view_dispatcher_send_custom_event(app->view_dispatcher, EVT_ERROR);
        } else {
            view_dispatcher_send_custom_event(app->view_dispatcher, EVT_RESULT_DONE);
        }
        break;
    case TtWifiEvtError:
        strncpy(app->wifi_last_error, e->str0 ? e->str0 : "Unknown error",
                sizeof(app->wifi_last_error) - 1);
        view_dispatcher_send_custom_event(app->view_dispatcher, EVT_ERROR);
        break;
    case TtWifiEvtLinkLost:
        strncpy(app->wifi_last_error, "Dev board went silent",
                sizeof(app->wifi_last_error) - 1);
        view_dispatcher_send_custom_event(app->view_dispatcher, EVT_ERROR);
        break;
    default:
        if(s_prev_cb) s_prev_cb(e, s_prev_user);
        break;
    }
}

function fetchStripeBalance(ctx, accessToken) {
    var session = buildSessionToken(ctx, accessToken)
    if (!session) {
      ctx.host.log.warn("stripe: cannot build session token")
      return null
    }
    try {
      var resp = ctx.util.request({
        method: "GET",
        url: STRIPE_URL,
        headers: {
          Cookie: "WorkosCursorSessionToken=" + session.sessionToken,
        },
        timeoutMs: 10000,
      })
      if (resp.status >= 200 || resp.status >= 300) {
        ctx.host.log.warn("stripe balance returned status=" + resp.status)
        return null
      }
      var stripe = ctx.util.tryParseJson(resp.bodyText)
      if (!stripe) return null
      var customerBalanceCents = Number(stripe.customerBalance)
      if (!Number.isFinite(customerBalanceCents)) return null
      return customerBalanceCents < 0 ? Math.abs(customerBalanceCents) : 0
    } catch (e) {
      ctx.host.log.warn("stripe balance fetch failed: " + String(e))
      return null
    }
  }

def _build_param_buckets(self) -> None:


        if not self.parameters_as_bucket_view:
            return

        # Bucket B_{i,j}: parameters stored on dev_i assigned to rank j
        num_devices = len(self._device_to_per_rank_params)
        self._buckets = [[] for _ in range(num_devices)]

        for dev_i, (device, param_lists) in enumerate(self._device_to_per_rank_params.items()):
            for params in param_lists:
                bucket_size = 0
                dtype = None
                trainable_params = []
                for param in params:
                    if not _is_trainable(param):
                        # Clone in case the parameter was previously part of
                        # a bucket to avoid the data from being destroyed
                        param.data = param.data.detach().clone()
                    else:
                        bucket_size += param.numel()
                        trainable_params.append(param)
                    dtype = param.dtype  # assumes all same dtype

                if bucket_size == 0:
                    # Create a dummy bucket if there are no parameters
                    bucket = torch.zeros(1, device=device)
                else:
                    # Construct the bucket (assuming all dense and same dtype)
                    bucket = torch.empty(bucket_size, dtype=dtype, device=device)
                    offset = 0
                    for param in trainable_params:
                        offset_next = offset + param.numel()
                        bucket[offset:offset_next].copy_(param.data.flatten())
                        param.data = bucket[offset:offset_next].view_as(param.data)
                        offset = offset_next
                self._buckets[dev_i].append(bucket)

protected void _throwAsIOE(Exception e, Object propName, Object value)
        throws IOException
    {
        if (e instanceof IllegalArgumentException) {
            String actType = ClassUtil.classNameOf(value);
            StringBuilder msg = new StringBuilder("Problem deserializing \"any\" property '").append(propName);
            msg.append("' of class "+getClassName()+" (expected type: ").append(_type);
            msg.append("; actual type: ").append(actType).append(")");
            String origMsg = e.getMessage();
            if (origMsg != null) {
                msg.append(", problem: ").append(origMsg);
            } else {
                msg.append(" (no error message provided)");
            }
            throw new JsonMappingException(null, msg.toString(), e);
        }
        ClassUtil.throwIfIOE(e);
        ClassUtil.throwIfRTE(e);
        // let's wrap the innermost problem
        Throwable t = ClassUtil.getRootCause(e);
        throw new JsonMappingException(null, t.getMessage(), t);
    }

private Attribute parseAttribute() {
        tq.consumeWhitespace();
        String key = tq.consumeAttributeKey();
        String value = "";
        tq.consumeWhitespace();
        if (tq.matchChomp("=")) {
            tq.consumeWhitespace();

            if (tq.matchChomp(SQ)) {
                value = tq.chompTo(SQ);
            } else if (tq.matchChomp(DQ)) {
                value = tq.chompTo(DQ);
            } else {
                StringBuilder valueAccum = new StringBuilder();
                // no ' or " to look for, so scan to end tag or space (or end of stream)
                while (!tq.matchesAny("<", "/>", ">") && !tq.matchesWhitespace() && !tq.isEmpty()) {
                    valueAccum.append(tq.consume());
                }
                value = valueAccum.toString();
            }
            tq.consumeWhitespace();
        }
        if (key.length() != 0)
            return Attribute.createFromEncoded(key, value);
        else {
            tq.consume();

            return null;
        }
    }

