        BuildNewTic();
    }
    else
    {
        NetUpdate ();
    }
    lowtic = GetLowTic();
    availabletics = lowtic - gametic/ticdup;
    if (new_sync)
    {
	counts = availabletics;
    }
    else
    {
        if (realtics < availabletics-1)
            counts = realtics+1;
        else if (realtics < availabletics)
            counts = realtics;
        else
            counts = availabletics;
        if (counts < 1)
            counts = 1;
        if (net_client_connected)
        {
            OldNetSync();
        }
    }
    if (counts < 1)
	counts = 1;
    while (!PlayersInGame() || lowtic < gametic/ticdup + counts)
    {
