CJSON_PUBLIC(int) cJSON_GetArraySize(const cJSON *array)
{
    cJSON *child = NULL;
    size_t size = 0;
    if (array == NULL)
    {
        return 0;
    }
    child = array->child;
    while (child != NULL)
    {
        size++;
        child = child->next;
    }
    if (size > (size_t)INT_MAX)
    {
        return INT_MAX;
    }
    return (int)size;
}

