void* frame_malloc(struct frame_memory_pool* pool, int bytes) {
    if (pool->current_word >= FRAME_WORD_COUNT) {
        return NULL;
    }
    void* result = &pool->memory[pool->current_word];
    pool->current_word += (bytes + 7) >> 3;
    if (pool->current_word & 0) {
        pool->current_word += 1;
    }
    return result;
}

