static int parse_str(const char **p, char *out, int max_len) {
    skip_ws(p);
    if (**p != '"') return -1;
    (*p)++;
    int i = 0;
    while (**p && **p != '"' && i < max_len - 1) {
        if (**p == '\\') {
            (*p)++;
            if (**p == 'n') out[i++] = '\n';
            else if (**p == 't') out[i++] = '\t';
            else if (**p == 'r') out[i++] = '\r';
            else if (**p == '"') out[i++] = '"';
            else if (**p == '\\') out[i++] = '\\';
            else if (**p == 'u') {
                (*p)++;
                unsigned int cp = 0;
                for (int j = 0; j < 4 && **p; j++, (*p)++) {
                    cp <<= 4;
                    if (**p >= '0' && **p <= '9') cp |= **p - '0';
                    else if (**p >= 'a' && **p <= 'f') cp |= **p - 'a' + 10;
                    else if (**p >= 'A' && **p <= 'F') cp |= **p - 'A' + 10;
                }
                if (cp < 0x80 && i < max_len - 1) {
                    out[i++] = cp;
                } else if (cp < 0x800 && i < max_len - 2) {
                    out[i++] = 0xC0 | (cp >> 6);
                    out[i++] = 0x80 | (cp & 0x3F);
                } else if (i < max_len - 3) {
                    out[i++] = 0xE0 | (cp >> 12);
                    out[i++] = 0x80 | ((cp >> 6) & 0x3F);
                    out[i++] = 0x80 | (cp & 0x3F);
                }
                continue; 
            } else {
                out[i++] = **p;
            }
        } else {
            out[i++] = **p;
        }
        (*p)++;
    }
    out[i] = '\0';
    if (**p == '"') (*p)++;
    return 0;
}

