/* thread all the external pointers */
/* pass 1: thread the pointers and update the previous ones */
/* pass 2: update the threaded pointers and move the block to its
       final position */
/* update the source pointer in the parser */
/* rehash the object properties */
/* XXX: try to do it in the previous pass (add a specific tag ?) */

code:
static void gc_compact_heap(JSContext *ctx)
{
    uint8_t *ptr, *new_ptr;
    int size;
    JSValue *sp, *sp_end;
    sp_end = ctx->class_proto + 2 * ctx->class_count;
    for(sp = &ctx->unique_strings; sp < sp_end; sp++) {
        gc_thread_pointer(ctx, sp);
    }
    {
        int i;
        JSStringPosCacheEntry *ce;
        for(i = 0; i < JS_STRING_POS_CACHE_SIZE; i++) {
            ce = &ctx->string_pos_cache[i];
            gc_thread_pointer(ctx, &ce->str);
        }
    }
    for(sp = ctx->sp; sp < (JSValue *)ctx->stack_top; sp++) {
        gc_thread_pointer(ctx, sp);
    }
    {
        JSGCRef *ref;
        for(ref = ctx->top_gc_ref; ref != NULL; ref = ref->prev) {
            gc_thread_pointer(ctx, &ref->val);
        }
        for(ref = ctx->last_gc_ref; ref != NULL; ref = ref->prev) {
            gc_thread_pointer(ctx, &ref->val);
        }
    }
    if (ctx->parse_state) {
        JSParseState *ps = ctx->parse_state;
        gc_thread_pointer(ctx, &ps->source_str);
        gc_thread_pointer(ctx, &ps->filename_str);
        gc_thread_pointer(ctx, &ps->token.value);
        gc_thread_pointer(ctx, &ps->cur_func);
        gc_thread_pointer(ctx, &ps->byte_code);
    }
    new_ptr = ctx->heap_base;
    ptr = ctx->heap_base;
    while (ptr < ctx->heap_free) {
        gc_update_threaded_pointers(ctx, ptr, new_ptr);
        size = get_mblock_size(ptr);
        if (js_get_mtag(ptr) != JS_MTAG_FREE) {
            gc_thread_block(ctx, ptr);
            new_ptr += size;
        }
        ptr += size;
    }
    new_ptr = ctx->heap_base;
    ptr = ctx->heap_base;
    while (ptr < ctx->heap_free) {
        gc_update_threaded_pointers(ctx, ptr, new_ptr);
        size = get_mblock_size(ptr);
        if (js_get_mtag(ptr) != JS_MTAG_FREE) {
            if (new_ptr != ptr) {
                memmove(new_ptr, ptr, size);
            }
            new_ptr += size;
        }
        ptr += size;
    }
    ctx->heap_free = new_ptr;
    if (ctx->parse_state) {
        JSParseState *ps = ctx->parse_state;
        if (JS_IsPtr(ps->source_str)) {
            JSString *p = JS_VALUE_TO_PTR(ps->source_str);
            ps->source_buf = p->buf;
        }
    }
    ptr = ctx->heap_base;
    while (ptr < ctx->heap_free) {
        size = get_mblock_size(ptr);
        if (js_get_mtag(ptr) == JS_MTAG_OBJECT) {
            js_rehash_props(ctx, (JSObject *)ptr, TRUE);
        }
        ptr += size;
    }
}

static void sync_link_names_recursive(ParserContext *ctx, ASTNode *node)
{
    if (!node)
    {
        return;
    }
    if (node->type_info)
    {
        sync_type_linkage(ctx, node->type_info);
    }
    switch (node->type)
    {
    case NODE_FUNCTION:
        if (node->func.ret_type_info)
        {
            sync_type_linkage(ctx, node->func.ret_type_info);
        }
        if (node->func.arg_types)
        {
            for (int i = 0; i < node->func.arg_count; i++)
            {
                sync_type_linkage(ctx, node->func.arg_types[i]);
            }
        }
        sync_link_names_recursive(ctx, node->func.body);
        break;
    case NODE_STRUCT:
        sync_link_names_recursive(ctx, node->strct.fields);
        break;
    case NODE_VAR_DECL:
        sync_link_names_recursive(ctx, node->var_decl.init_expr);
        break;
    case NODE_BLOCK:
        sync_link_names_recursive(ctx, node->block.statements);
        break;
    case NODE_IF:
        sync_link_names_recursive(ctx, node->if_stmt.condition);
        sync_link_names_recursive(ctx, node->if_stmt.then_body);
        sync_link_names_recursive(ctx, node->if_stmt.else_body);
        break;
    case NODE_RETURN:
        sync_link_names_recursive(ctx, node->ret.value);
        break;
    case NODE_EXPR_CALL:
        sync_link_names_recursive(ctx, node->call.callee);
        sync_link_names_recursive(ctx, node->call.args);
        break;
    case NODE_EXPR_BINARY:
        sync_link_names_recursive(ctx, node->binary.left);
        sync_link_names_recursive(ctx, node->binary.right);
        break;
    case NODE_EXPR_UNARY:
        sync_link_names_recursive(ctx, node->unary.operand);
        break;
    case NODE_EXPR_MEMBER:
        sync_link_names_recursive(ctx, node->member.target);
        break;
    case NODE_EXPR_CAST:
        sync_link_names_recursive(ctx, node->cast.expr);
        break;
    case NODE_ROOT:
        sync_link_names_recursive(ctx, node->root.children);
        break;
    default:
        break;
    }
    sync_link_names_recursive(ctx, node->next);
}

