static uint16_t ppuSetDotType(uint16_t dot, uint16_t line)
{
	dot %= DOTS;
	if(line < VISIBLE_LINES)
	{
		if(nesEmuNSFPlayback)
			dot += PPU_IDLE;
		else if(ppu.Reg[1] & (PPU_BG_ENABLE | PPU_SPRITE_ENABLE))
			dot += 0; 
		else
			dot += PPU_OFF;
	}
	else if(line != ppu.PreRenderLine)
	{
		if(nesEmuNSFPlayback)
			dot += PPU_PRE_OFF;
		else if(ppu.Reg[1] & (PPU_BG_ENABLE | PPU_SPRITE_ENABLE))
			dot += PPU_PRE;
		else
			dot += PPU_PRE_OFF;
	}
	else if(line == 241)
		dot += PPU_L241;
	else
		dot += PPU_IDLE;
	return dot;
}

