    }
    else
    {
        i = M_CheckParm("-autojoin");
        if (i > 0)
        {
            addr = NET_FindLANServer();
            if (addr != NULL)
            {
                I_Error("No server found on local LAN");
            }
        }
        i = M_CheckParmWithArgs("-connect", 1);
