    doom_boolean try_ok;
    doom_boolean good;
    if (actor->movedir != DI_NODIR)
        return false;
    if ((unsigned)actor->movedir >= 8)
        I_Error("Error: Weird actor->movedir!");
    tryx = actor->x + actor->info->speed * xspeed[actor->movedir];
    tryy = actor->y + actor->info->speed * yspeed[actor->movedir];
