    event_t event;
    int pressed;
    unsigned char key;
	while (DG_GetKey(&pressed, &key))
    {
        UpdateShiftStatus(pressed, key);
        if (pressed)
        {
            event.type = ev_keydown;
            event.data1 = TranslateKey(key);
            event.data2 = GetTypedChar(key);
            if (event.data1 != 0)
            {
                D_PostEvent(&event);
            }
        }
        else
        {
            event.type = ev_keyup;
            event.data1 = TranslateKey(key);
            event.data2 = 0;
            if (event.data1 != 0)
            {
                D_PostEvent(&event);
            }
            break;
        }
    }
