    }
    if (r.source === 'events') byKey.set(r.key, { ...prev, ...r });
    else byKey.set(r.key, { ...r, ...prev });
  }
  const merged = Array.from(byKey.values()).sort((a, b) => b.score - a.score);
  process.stdout.write(`Repo: ${repoRoot}\n`);
