                return _msc_init_for_dn(cbw);
            case READ_10:
                usb_debug("READ(10)\n");
                return _scsi_handle_read_or_write_command(cbw, SCSI_DIR_IN);
            case WRITE_10:
                usb_debug("WRITE(10)\n");
