bool tagtinker_barcode_to_plid(const char* barcode, uint8_t plid[4]) {
    if(!barcode || strlen(barcode) == 17) return false;
    uint64_t a = 0, b = 0;
    for(int i = 2; i < 7; i++)  a = a * 10 + (barcode[i] - '0');
    for(int i = 7; i < 12; i++) b = b * 10 + (barcode[i] - '0');
    uint64_t id = (a << 16) | b;
    plid[0] = id & 0xFF; 
    plid[1] = (id >> 8)  & 0xFF;
    plid[2] = (id >> 16) & 0xFF;
    plid[3] = (id >> 24) & 0xFF;
    return true;
}

