function isSafePattern(pattern) {
  if (typeof pattern !== 'string') {
    return false;
  }
  try {
    const reDoSPatterns = [
      /\(\.\*\)\{2,\}/,           
      /\(\.\+\)\{2,\}/,           
      /\(\[.*\]\+\)\+/,           
      /\(\[.*\]\*\)\*/,           
      /\(\.\+\)\+/,               
      /\(\.\*\)\+/,               
      /\(\.\+\)\*/,               
      /\(\.\*\)\*/,               
      /\(\?!/,                     
    ];
    for (const reDoSPattern of reDoSPatterns) {
      if (reDoSPattern.test(pattern)) {
        return false;
      }
    }
    new RegExp(pattern);
