static int ecb_des_encrypt(struct skcipher_request *req)
{
        struct ifx_deu_des_ctx *ctx = crypto_tfm_ctx(req->base.tfm);
        struct skcipher_walk walk;
        int err;
        unsigned int enc_bytes, nbytes;
        err = skcipher_walk_virt(&walk, req, false);
        while ((nbytes = enc_bytes = walk.nbytes)) {
                enc_bytes -= (nbytes % DES_BLOCK_SIZE);
                ifx_deu_des_ecb(ctx, walk.dst.virt.addr, walk.src.virt.addr,
                               NULL, enc_bytes, CRYPTO_DIR_ENCRYPT, 1);
                nbytes &= DES_BLOCK_SIZE - 1;
                err = skcipher_walk_done(&walk, nbytes);
        }
        return err;
}

static void js_shrink_value_array(JSContext *ctx, JSValue *pval, int new_size)
{
    JSValueArray *arr;
    if (*pval == JS_NULL)
        return;
    arr = JS_VALUE_TO_PTR(*pval);
    assert(new_size <= arr->size);
    if (new_size == 0) {
        js_free(ctx, arr);
        *pval = JS_NULL;
    } else {
        arr = js_shrink(ctx, arr, sizeof(JSValueArray) + new_size * sizeof(JSValue));
        arr->size = new_size;
    }
}

