    const geneA = genes.find(g => g.id === 'gene_a');
    assert.ok(geneA);
    assert.equal(geneA.category, 'optimize');
  });
  it('preserves on-disk gene shape (does not synthesize default fields that would invalidate asset_id)', () => {
