    const { computeAssetId, verifyAssetId } = require('../src/gep/contentHash');
    const legacyGene = {
      type: 'Gene',
      id: 'gene_legacy',
      category: 'repair',
      signals_match: ['error'],
      strategy: ['fix it'],
