    if (strchr(pattern, '|'))
    {
        char *pattern_copy = xstrdup(pattern);
        char *saveptr;
        char *part = strtok_r(pattern_copy, "|", &saveptr);
        int first = 1;
        EMIT(ctx, "(");
        while (part)
        {
            if (!first)
            {
                EMIT(ctx, " || ");
            }
            EnumVariantReg *reg = find_enum_variant(ctx, part);
            if (reg)
            {
                int simple = is_simple_enum(ctx, reg->enum_name);
                if (simple)
