code:
static int hostapd_dfs_start_channel_switch(struct hostapd_iface *iface)
{
	struct hostapd_channel_data *channel;
	int secondary_channel;
	u8 oper_centr_freq_seg0_idx;
	u8 oper_centr_freq_seg1_idx;
	enum dfs_channel_type channel_type = DFS_AVAILABLE;
	u8 current_vht_oper_chwidth = hostapd_get_oper_chwidth(iface->conf);
	wpa_printf(MSG_DEBUG, "%s called (CAC active: %s, CSA active: %s)",
		   __func__, iface->cac_started ? "yes" : "no",
		   hostapd_csa_in_progress(iface) ? "yes" : "no");
	if (hostapd_csa_in_progress(iface))
		return 0;
	if (iface->cac_started)
		return hostapd_dfs_start_channel_switch_cac(iface);
	if (iface->dfs_domain != HOSTAPD_DFS_REGION_ETSI)
		channel_type = DFS_ANY_CHANNEL;
	channel = dfs_get_valid_channel(iface, &secondary_channel,
					&oper_centr_freq_seg0_idx,
					&oper_centr_freq_seg1_idx,
					channel_type);
	if (!channel) {
		channel_type = DFS_ANY_CHANNEL;
		channel = dfs_downgrade_bandwidth(iface, &secondary_channel,
						  &oper_centr_freq_seg0_idx,
						  &oper_centr_freq_seg1_idx,
						  &channel_type);
		if (!channel) {
			hostapd_disable_iface(iface);
			hostapd_enable_iface(iface);
			return 0;
		}
		if (channel_type == DFS_ANY_CHANNEL) {
			iface->freq = channel->freq;
			iface->conf->channel = channel->chan;
			iface->conf->secondary_channel = secondary_channel;
			hostapd_set_oper_centr_freq_seg0_idx(
				iface->conf, oper_centr_freq_seg0_idx);
			hostapd_set_oper_centr_freq_seg1_idx(
				iface->conf, oper_centr_freq_seg1_idx);
			hostapd_disable_iface(iface);
			hostapd_enable_iface(iface);
			return 0;
		}
	}
	return hostapd_dfs_request_channel_switch(iface, channel->chan,
						  channel->freq,
						  secondary_channel,
						  current_vht_oper_chwidth,
						  oper_centr_freq_seg0_idx,
						  oper_centr_freq_seg1_idx);
}

function balance_noise(gfp, cod_info, distort, xrpow, bRefine) {
    var gfc = gfp.internal_flags;
    amp_scalefac_bands(gfp, cod_info, distort, xrpow, bRefine);
    var status = loop_break(cod_info);
    if (status)
        return false;
    if (gfc.mode_gr == 2)
        status = tk.scale_bitcount(cod_info);
    else
        status = tk.scale_bitcount_lsf(gfc, cod_info);
    if (!status)
        return true;
    if (gfc.noise_shaping > 1) {
        Arrays.fill(gfc.pseudohalf, 0);
        if (0 == cod_info.scalefac_scale) {
            inc_scalefac_scale(cod_info, xrpow);
            status = false;
        } else {
            if (cod_info.block_type == Encoder.SHORT_TYPE
                && gfc.subblock_gain > 0) {
                status = (inc_subblock_gain(gfc, cod_info, xrpow) || loop_break(cod_info));
            }
        }
    }
    if (!status) {
        if (gfc.mode_gr == 2)
            status = tk.scale_bitcount(cod_info);
        else
            status = tk.scale_bitcount_lsf(gfc, cod_info);
    }
    return !status;
}

