    tmpreg1 = ADCx->SMPR2;
    tmpreg2 = SMPR2_SMP_Set << (3 * ADC_Channel);
    tmpreg1 &= ~tmpreg2;
    tmpreg2 = (uint32_t)ADC_SampleTime << (3 * ADC_Channel);
    tmpreg1 |= tmpreg2;
    ADCx->SMPR2 = tmpreg1;
