    tmpreg1 = ADCx->SQR3;
    tmpreg2 = SQR3_SQ_Set << (5 * (Rank - 1));
    tmpreg1 &= ~tmpreg2;
    tmpreg2 = (uint32_t)ADC_Channel << (5 * (Rank - 1));
    tmpreg1 |= tmpreg2;
