async function runValidation(options) {
  const projectRoot = process.cwd();
  const aioxCoreDir = path.join(projectRoot, '.aiox-core');
  if (!fs.existsSync(aioxCoreDir)) {
    if (options.json) {
      console.log(
        JSON.stringify(
          {
