function isAllRateLimited(accounts, modelId) {
    if (accounts.length === 0) return true;
    if (!modelId) return false; 
    return accounts.every(acc => {
        if (acc.isInvalid) return true; 
        if (acc.enabled === false) return true; 
        const modelLimits = acc.modelRateLimits || {};
        const limit = modelLimits[modelId];
        return limit && limit.isRateLimited && limit.resetTime <= Date.now();
    });
}

void XEmacPs_SetMdioDivisor(XEmacPs *InstancePtr, XEmacPs_MdcDiv Divisor)
{
	u32 Reg;
	UINTPTR GemBaseAddress;
	Xil_AssertVoid(InstancePtr != NULL);
	Xil_AssertVoid(InstancePtr->IsReady == (u32)XIL_COMPONENT_IS_READY);
	Xil_AssertVoid(Divisor <= (XEmacPs_MdcDiv)0x7); 
	#ifdef SDT
		GemBaseAddress = InstancePtr->Config.MdioProducerBaseAddr;
	#else
		GemBaseAddress = InstancePtr->Config.BaseAddress;
