			mmc3_prgROMadd = 0;
			mmc3_prgROMand = 0x1FFFF;
			mmc3SetChrROMadd(0);
			mmc3_chrROMand = 0x1FFFF;
			break;
		case 1:
			mmc3_prgROMadd = 0x20000;
			mmc3_prgROMand = 0x1FFFF;
			mmc3SetChrROMadd(0x20000);
			mmc3_chrROMand = 0x1FFFF;
			break;
		case 2:
			mmc3_prgROMadd = 0x40000;
			mmc3_prgROMand = 0x1FFFF;
			mmc3SetChrROMadd(0x40000);
			mmc3_chrROMand = 0x1FFFF;
			break;
		case 3:
			mmc3_prgROMadd = 0x60000;
			mmc3_prgROMand = 0x1FFFF;
			mmc3SetChrROMadd(0x60000);
			mmc3_chrROMand = 0x1FFFF;
			break;
